var n=`1094-samlor-korko`;var a=`world-1094`;var s=`KH`;var t=`southeast-asia`;var o=4;var r=78;var m={en:`Samlor Korko`,ua:`Самлор корко`};var g={en:`Samlor Korko is a dish from Cambodia prepared with lemongrass, galangal, fish sauce, pumpkin. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Самлор корко, страва кухні країни Камбоджа, яку готують із таких продуктів: лемонграс, галангал, рибний соус, гарбуз. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 25 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 25 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:25,i:[[`chicken-stock`,850,`ml`],[`lemongrass`,2,`pcs`],[`galangal`,35,`g`],[`fish-sauce`,20,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`pumpkin`,280,`g`],[`eggplant`,260,`g`],[`green-beans`,170,`g`],[`pork-belly`,350,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`rice-flour`,40,`g`],[`water`,100,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`thai-basil`,25,`g`]]}];var d={slug:n,id:a,country:`KH`,region:t,servings:4,minutes:78,title:m,text:g,steps:l};export{s as country,d as default,a as id,r as minutes,t as region,o as servings,n as slug,l as steps,g as text,m as title};